parameters.jsCode:
// Extract top 3 fresh articles and check timestamp
const items = $input.all().slice(0, 3);
return items.map(item => ({
  json: {
    rawTitle: item.json.title,
    rawLink: item.json.link,
    rawContent: item.json.contentSnippet || item.json.content || item.json.description,
    sourceName: 'TechCrunch Wire',
    pubDate: item.json.pubDate
  }
}));

parameters.prompt:
=You are the Senior Technical Editor at TechPulse Journal. Transform the following raw wire story into an authoritative, in-depth tech article:

Raw Headline: {{$json.rawTitle}}
Raw Content: {{$json.rawContent}}
Source URL: {{$json.rawLink}}

Output STRICT JSON with the following schema:
{
  "title": "Compelling, objective editorial headline",
  "slug": "url-friendly-slug",
  "excerpt": "2-sentence executive summary",
  "content": "Full markdown body (minimum 3 paragraphs) with ## and ### headings, key technical specifications, bullet points, and an illustrative python/code block or benchmark if applicable.",
  "category": "AI | Technology | Crypto | Business | Science | Startups | Cybersecurity | Gadgets",
  "tags": ["Tag1", "Tag2", "Tag3"],
  "featured_image": "https://images.unsplash.com/photo-1518770660439-4636190af475?w=1200"
}
